#!/usr/bin/env bash
# Writes the client IDs into Sources/StowSecrets/BundledAppConfigValues.generated.swift
# for a bundled-config build (D-512). The generated file is git-ignored and compiled
# only with -DSTOW_BUNDLED_CONFIG:
#
#   scripts/bundle-config.sh ~/Library/Application\ Support/Stow/config.env
#   swift build -c release -Xswiftc -DSTOW_BUNDLED_CONFIG
#
# Values are never printed. With --clean, deletes the generated file.
set -euo pipefail
cd "$(dirname "$0")/.."
out=Sources/StowSecrets/BundledAppConfigValues.generated.swift

if [ "${1:-}" = "--clean" ]; then
    trash "$out"
    exit 0
fi
[ $# -eq 1 ] && [ -f "$1" ] || { echo "usage: $0 <config file> | --clean" >&2; exit 1; }
git check-ignore -q "$out" || { echo "bundle-config: $out is not git-ignored; refusing" >&2; exit 1; }

keys=(STOW_GOOGLE_CLIENT_ID STOW_GOOGLE_CLIENT_SECRET STOW_MS_CLIENT_ID STOW_MS_TENANT)
umask 077
trap 'rm -f "$out.tmp"' EXIT
{
    echo "// Generated by scripts/bundle-config.sh. Git-ignored; never commit (D-512)."
    echo "#if STOW_BUNDLED_CONFIG"
    echo "enum BundledAppConfigValues {"
    echo "    static let values: [String: String] = ["
    for key in "${keys[@]}"; do
        # The last KEY=value line wins, as in AppConfig.parseEnvFile; quotes are stripped.
        line="$(grep -E "^[[:space:]]*(export[[:space:]]+)?$key[[:space:]]*=" "$1" | tail -n 1 || true)"
        value="${line#*=}"
        value="$(printf '%s' "$value" | sed -E 's/^[[:space:]]+//; s/[[:space:]]+$//; s/^"(.*)"$/\1/; s/^'"'"'(.*)'"'"'$/\1/')"
        if [ -z "$value" ] || [[ "$value" == *REPLACE_ME* ]]; then
            echo "bundle-config: $key is missing or a placeholder in $1" >&2
            exit 1
        fi
        case "$value" in *[!A-Za-z0-9._-]*) echo "bundle-config: $key has characters a client ID never has" >&2; exit 1 ;; esac
        echo "        \"$key\": \"$value\","
    done
    echo "    ]"
    echo "}"
    echo "#endif"
} > "$out.tmp"
mv "$out.tmp" "$out"
echo "Wrote $out (values not shown). Build with -Xswiftc -DSTOW_BUNDLED_CONFIG."
